import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.D8Tso2Ul.js";const m=JSON.parse('{"title":"Fases de obra","description":"","frontmatter":{},"headers":[],"relativePath":"ds44/fases-obra.md","filePath":"ds44/fases-obra.md"}'),o={name:"ds44/fases-obra.md"};function i(d,a,r,c,l,p){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="fases-de-obra" tabindex="-1">Fases de obra <a class="header-anchor" href="#fases-de-obra" aria-label="Permalink to &quot;Fases de obra&quot;">​</a></h1><p>Build &amp; Serve maneja <strong>dos dimensiones de fases</strong> que conviene no confundir:</p><ol><li><strong>Fase física</strong> de construcción — el avance real de la obra.</li><li><strong>Ciclo normativo (Deming / PDCA)</strong> — la lógica de gestión preventiva del DS 44.</li></ol><h2 id="fases-fisicas" tabindex="-1">Fases físicas <a class="header-anchor" href="#fases-fisicas" aria-label="Permalink to &quot;Fases físicas&quot;">​</a></h2><p>El campo <code>etapaActual</code> de la tabla <code>ObrasTable</code> registra la etapa física actual:</p><table tabindex="0"><thead><tr><th>Etapa</th><th>Código</th><th>Descripción</th></tr></thead><tbody><tr><td>Excavación</td><td><code>excavacion</code></td><td>Movimiento de tierras, fundaciones, inicio de faena</td></tr><tr><td>Obra gruesa</td><td><code>obra_gruesa</code></td><td>Estructura, hormigón, albañilería</td></tr><tr><td>Terminaciones</td><td><code>terminaciones</code></td><td>Instalaciones, revestimientos, acabados</td></tr><tr><td>Entrega</td><td><code>entrega</code></td><td>Cierre, recepción y entrega de la obra</td></tr></tbody></table><p>Cada fase tiene asociado un conjunto de <strong>documentos obligatorios</strong> en el campo <code>fasesConfig</code>, que se prellenan al crear la obra:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fasesConfig:</span></span>
<span class="line"><span>  excavacion:     [IRL, POLITICA_SSO, REGLAMENTO_INTERNO, ENCUESTA_SALUD, ...]</span></span>
<span class="line"><span>  obra_gruesa:    [PROCEDIMIENTO_TRABAJO, ENTREGA_EPP, MAPA_RIESGOS, ...]</span></span>
<span class="line"><span>  terminaciones:  [PROCEDIMIENTO_TRABAJO, ENTREGA_EPP, ...]</span></span>
<span class="line"><span>  entrega:        [CAPACITACION_SST, ...]</span></span></code></pre></div><h2 id="avance-de-fase-con-verificacion" tabindex="-1">Avance de fase con verificación <a class="header-anchor" href="#avance-de-fase-con-verificacion" aria-label="Permalink to &quot;Avance de fase con verificación&quot;">​</a></h2><p>Al cambiar <code>etapaActual</code>, la plataforma puede <strong>verificar automáticamente</strong> si todos los documentos obligatorios de la fase anterior se encuentran firmados (estado <code>completado</code>). Esto evita avanzar en la obra dejando brechas de cumplimiento documental.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────┐   verifica    ┌──────────────┐   verifica    ┌────────────────┐</span></span>
<span class="line"><span>│  Excavación  │ ───────────▶ │  Obra gruesa │ ───────────▶ │  Terminaciones │ ──▶ Entrega</span></span>
<span class="line"><span>└──────────────┘  docs OK ✓   └──────────────┘  docs OK ✓   └────────────────┘</span></span></code></pre></div><h2 id="el-ciclo-de-deming-pdca" tabindex="-1">El ciclo de Deming (PDCA) <a class="header-anchor" href="#el-ciclo-de-deming-pdca" aria-label="Permalink to &quot;El ciclo de Deming (PDCA)&quot;">​</a></h2><p>Independiente de la etapa física, el DS 44 exige un ciclo continuo de mejora. La plataforma lo modela así:</p><table tabindex="0"><thead><tr><th>Etapa PDCA</th><th>En la plataforma</th></tr></thead><tbody><tr><td><strong>Planificar</strong></td><td>Definir MIPPER, política SSO, procedimientos y documentos por fase</td></tr><tr><td><strong>Hacer</strong></td><td>Ejecutar capacitaciones, entregar EPP, registrar actividades</td></tr><tr><td><strong>Verificar</strong></td><td>Auditorías, inspecciones, seguimiento de KPIs e incidentes</td></tr><tr><td><strong>Actuar</strong></td><td>Acciones correctivas, actualización de matrices y procedimientos</td></tr></tbody></table><p>Una obra avanza simultáneamente en su fase física (qué se está construyendo) y en su ciclo de gestión (cómo se gestiona la prevención). Ambas quedan trazadas en el módulo de <a href="/manual/modulos/obras.html">Obras</a>.</p><div class="info custom-block"><p class="custom-block-title">Configuración por tenant</p><p>Qué fases aplican a una obra depende de <code>tenant.reglas.fasesObligatorias</code>. Un tenant puede personalizar qué etapas exige y qué documentos son obligatorios en cada una. Ver <a href="/manual/modulos/tenants.html">Tenants</a>.</p></div>`,16)])])}const g=e(o,[["render",i]]);export{m as __pageData,g as default};
